import type { ContactInput } from '../../shared/contact';

type AmplifyOutputs = { custom?: { contactUrl?: string } };

// amplify_outputs.json is generated by the Amplify backend deploy. It's optional so the
// site still builds without a backend (local dev, previews).
const outputs = Object.values(
  import.meta.glob<AmplifyOutputs>('/amplify_outputs.json', { eager: true, import: 'default' }),
)[0];

export class ContactSubmitError extends Error {
  override name = 'ContactSubmitError';
}

/** The contact endpoint: `VITE_CONTACT_URL` wins (local dev), then the Amplify output. */
export function getContactUrl(): string | undefined {
  return import.meta.env.VITE_CONTACT_URL || outputs?.custom?.contactUrl || undefined;
}

/** Sends the message to the contact Lambda. Throws ContactSubmitError on any failure. */
export async function submitContact(input: ContactInput): Promise<void> {
  const url = getContactUrl();
  if (!url) throw new ContactSubmitError('Contact endpoint is not configured');

  let response: Response;
  try {
    response = await fetch(url, {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify(input),
    });
  } catch (cause) {
    throw new ContactSubmitError('Network error', { cause });
  }

  if (!response.ok) throw new ContactSubmitError(`Contact endpoint returned ${response.status}`);
}
